const CRYPTO = new Set(['ETH','XRP','SUI','BTC','SOL','ADA','DOGE']);
const SKIP   = ['CASH','OPTIONS','OPTION'];

// LSE stocks not on Finnhub free tier — null means fall back to Google Sheets price in Process Data
function finnhubSym(ticker, currency, exchange) {
  const t = ticker.trim().toUpperCase();
  if (CRYPTO.has(t)) return null;
  if (exchange === 'LON' || exchange === 'LSE' || currency === 'GBX') return null;
  return t;
}

const symbols = [...new Set(
  $input.all()
    .filter(r => {
      const t = (r.json.Ticker || '').toUpperCase();
      return t && !SKIP.some(s => t.includes(s));
    })
    .map(r => finnhubSym(r.json.Ticker || '', r.json.Currency || '', r.json.Exchange || ''))
    .filter(Boolean)
)];

// One item per symbol — HTTP: Finnhub Quote runs once per item
return symbols.map(sym => ({ json: { symbol: sym } }));

// Zip symbol names (from Code: Build Symbols) with Finnhub quote responses
const symbolItems = $('Code: Build Symbols').all();
const quoteItems  = $input.all();

const allPrices = {};
for (let i = 0; i < symbolItems.length; i++) {
  const sym   = symbolItems[i]?.json?.symbol;
  const quote = quoteItems[i]?.json;
  if (!sym || !quote) continue;
  const price = quote.c || quote.pc; // current price, fallback to previous close
  if (price) allPrices[sym] = { price: String(price) };
}

return [{ json: allPrices }];

const allRows  = $('Google Sheets').all();
const priceData = $('Code: Merge Prices').first().json;
const fxData    = $('HTTP: FX Rate').first().json;
const cgData    = $input.first().json;
const sheetRate = $('Google Sheets').first().json['ExcRate'];
const gbpUsd    = (sheetRate > 0) ? sheetRate : (fxData.rates?.USD || 1.27);
const today     = new Date().toISOString().split('T')[0];

// Sheet cells carry stray trailing spaces ('Growth ' vs 'Growth'), which split
// categories into duplicate slices downstream. Normalise every text field.
const clean = v => String(v ?? '').trim();

// Price map from Finnhub — plain US tickers
const priceMap = {};
for (const [sym, data] of Object.entries(priceData || {})) {
  if (data?.price) priceMap[sym] = parseFloat(data.price);
}

// CoinGecko map: ticker -> GBP price
const CG_IDS = { BTC:'bitcoin', ETH:'ethereum', XRP:'ripple', SUI:'sui', SOL:'solana' };
const cgMap  = {};
for (const [ticker, id] of Object.entries(CG_IDS)) {
  if (cgData[id]) cgMap[ticker] = cgData[id].gbp;
}

const CRYPTO = new Set(Object.keys(CG_IDS));

function finnhubSym(ticker, currency, exchange) {
  const t = ticker.trim().toUpperCase();
  if (CRYPTO.has(t)) return null;
  if (exchange === 'LON' || exchange === 'LSE' || currency === 'GBX') return null;
  return t;
}

return allRows
  .filter(r => !!clean(r.json.Ticker))
  .map(r => {
    const ticker     = clean(r.json.Ticker);
    const currency   = clean(r.json.Currency) || 'GBP';
    const exchange   = clean(r.json.Exchange);
    const brokerage  = clean(r.json.Brokerage);
    const shareCount = parseFloat(String(r.json['Share Count'] || '0').replace(/,/g, '')) || 0;
    const avgCostRaw = parseFloat(String(r.json['Avg Cost']    || '0').replace(/[£$,]/g, '')) || 0;
    const sheetGbp   = parseFloat(String(r.json['GBP']         || '0').replace(/[£$,]/g, '')) || 0;
    const t          = ticker.toUpperCase();
    const isCash     = t === 'CASH';
    const isOption   = t.includes('OPTION');

    let gbpPrice  = 0;
    let gbpValue  = 0;
    let taxFactor = 1;  // net-of-tax haircut implied by the sheet (e.g. KNOS scheme shares at 0.58)

    if (isCash || isOption) {
      gbpValue = sheetGbp;
    } else if (CRYPTO.has(t) && cgMap[t] != null) {
      gbpPrice = cgMap[t];
      gbpValue = shareCount > 0 ? gbpPrice * shareCount : sheetGbp;
    } else {
      const sym = finnhubSym(ticker, currency, exchange);
      const raw = sym != null ? priceMap[sym] : null;
      if (raw != null) {
        gbpPrice = currency === 'USD' ? raw / gbpUsd : raw;
        gbpValue = shareCount > 0 ? gbpPrice * shareCount : sheetGbp;
      } else {
        // No live price — this is every LSE ticker. The sheet's GBP column is a
        // live GOOGLEFINANCE formula that already applies any tax haircut, so
        // trust it instead of recomputing, and reuse the implied factor below
        // so the cost basis stays on the same net-of-tax footing.
        const sheetPrice = parseFloat(String(r.json['Share Price'] || '0').replace(/[£$,]/g, '')) || 0;
        if (currency === 'USD')      gbpPrice = sheetPrice / gbpUsd;
        else if (currency === 'GBX') gbpPrice = sheetPrice / 100;
        else                         gbpPrice = sheetPrice;

        const gross = gbpPrice * shareCount;
        if (sheetGbp > 0 && gross > 0) {
          gbpValue = sheetGbp;
          const implied = sheetGbp / gross;
          // Only a clear reduction counts as a deliberate haircut; anything near
          // 1 is rounding or a momentarily stale cell, not a tax adjustment.
          if (implied < 0.95) taxFactor = implied;
        } else {
          gbpValue = gross > 0 ? gross : sheetGbp;
        }
      }
    }

    let avgCostGbp;
    if (currency === 'GBX')      avgCostGbp = avgCostRaw / 100;
    else if (currency === 'USD') avgCostGbp = avgCostRaw / gbpUsd;
    else                         avgCostGbp = avgCostRaw;
    avgCostGbp *= taxFactor;

    const invested        = (isCash || isOption) ? 0 : avgCostGbp * shareCount;
    const unrealisedPl    = (isCash || isOption) ? 0 : gbpValue - invested;
    const unrealisedPlPct = (!isCash && !isOption && invested > 0) ? (unrealisedPl / invested) * 100 : 0;

    return { json: {
      snapshot_date:        today,
      brokerage,
      exchange,
      ticker,
      category:             clean(r.json.Category),
      sector:               clean(r.json.Sector),
      region:               clean(r.json.Region),
      currency,
      share_price:          gbpPrice,
      share_count:          shareCount,
      gbp_value:            gbpValue,
      avg_cost:             avgCostGbp,
      fx_rate:              gbpUsd,
      unrealised_pl:        unrealisedPl,
      unrealised_pl_pct:    unrealisedPlPct,
      dividend:             parseFloat(String(r.json.Dividend           || '0').replace(/[£$,]/g, '')) || 0,
      dividend_pct:         parseFloat(String(r.json['Dividend %']      || '0').replace(/[£$,]/g, '')) || 0,
      dividend_return:      parseFloat(String(r.json['Dividend Return'] || '0').replace(/[£$,]/g, '')) || 0
    }};
  });

const rows  = $input.all();
const today = rows[0]?.json.snapshot_date || new Date().toISOString().split('T')[0];

let totalGbpValue = 0, totalUnrealisedPl = 0, totalInvested = 0, cashGbp = 0;
for (const r of rows) {
  totalGbpValue     += r.json.gbp_value     || 0;
  totalUnrealisedPl += r.json.unrealised_pl || 0;
  if (r.json.category === 'Cash') {
    cashGbp += r.json.gbp_value || 0;
  } else {
    totalInvested += (r.json.avg_cost || 0) * (r.json.share_count || 0);
  }
}
const unrealisedPlPct = totalInvested > 0 ? (totalUnrealisedPl / totalInvested) * 100 : 0;

return [{ json: {
  snapshot_date:           today,
  total_gbp_value:         totalGbpValue,
  total_unrealised_pl:     totalUnrealisedPl,
  total_unrealised_pl_pct: unrealisedPlPct,
  cash_gbp:                cashGbp,
  invested_gbp:            totalInvested
} }];
